<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {runsStore} from '../stores/runs';import {get} from '../api/runs';import {create as createPlan} from '../api/plans';import {canEdit} from '../stores/auth';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import MetricStrip from '../components/common/MetricStrip.vue';import CurvePlot from '../components/common/CurvePlot.vue';import PipeTable from '../components/common/PipeTable.vue';import {pct} from '../utils/format';const {items,error,reload}=runsStore(),route=useRoute(),router=useRouter(),selected=ref<any>(null),budget=ref(40);const task=useTask();async function select(id:string){await task.execute(async()=>{selected.value=await get(id)})}onMounted(async()=>{await reload();const id=String(route.query.run||'run-demo');await select(id)});usePolling(()=>{if(selected.value&&['queued','running'].includes(selected.value.status))select(selected.value.id)});function plan(){task.execute(async()=>{await createPlan({name:'城北巡检 · '+new Date().toLocaleDateString('zh-CN'),run_id:selected.value.id,budget:budget.value});router.push('/plans')})}</script><template><PageTitle eyebrow="04 / EVIDENCE REVIEW" title="看清效果，也看清代价。" description="曲线、系数与排序均来自后端实际计算；阈值选择不使用留出集标签。"/><Notice :error="error||task.error.value"/><div class="run-select"><label>选择分析运行 <select :value="selected?.id" @change="select(($event.target as HTMLSelectElement).value)"><option v-for="r in items" :key="r.id" :value="r.id">{{r.id}} / {{r.status}}</option></select></label><StatusBadge v-if="selected" :status="selected.status"/></div><template v-if="selected?.result"><MetricStrip :items="[{label:'ROC AUC',value:pct(selected.result.metrics.roc_auc)},{label:'平均精确率 AP',value:pct(selected.result.metrics.average_precision)},{label:'留出集召回率',value:pct(selected.result.metrics.recall)},{label:'训练 OOF 阈值',value:selected.result.threshold_selection.threshold.toFixed(3)}]"/><div class="chart-pair"><CurvePlot :points="selected.result.roc" title="ROC / 检出与误报"/><CurvePlot :points="selected.result.pr" title="PR / 精确率与召回率"/></div><div class="analysis-grid"><section><div class="section-heading"><h2>哪些因素影响排序</h2><small>标准化逻辑回归系数</small></div><div v-for="c in selected.result.coefficients" :key="c.feature" class="coefficient"><span class="mono">{{c.feature}}</span><div><i :style="{width:Math.min(100,Math.abs(c.coefficient)*38)+'%'}" :class="{negative:c.coefficient<0}"></i></div><b class="mono">{{c.coefficient.toFixed(3)}}</b></div></section><section class="method-note"><h2>留出集混淆矩阵</h2><div class="confusion"><span>正确排除 <b>{{selected.result.metrics.tn}}</b></span><span>误报 <b>{{selected.result.metrics.fp}}</b></span><span>漏检 <b>{{selected.result.metrics.fn}}</b></span><span>检出 <b>{{selected.result.metrics.tp}}</b></span></div><p>训练 {{selected.result.training_count}} 条 / 留出 {{selected.result.holdout_count}} 条；最佳 C={{selected.result.best_C}}。预算很小时召回率下降，应结合漏检成本复核。</p></section></div><section class="section-block"><div class="section-heading"><h2>风险排序 / 前 12 段</h2><div class="inline-form"><label>预算 <input v-model.number="budget" type="number" min="1" max="5000"></label><button :disabled="!canEdit||task.busy.value" @click="plan">生成待审清单 ↗</button></div></div><PipeTable :pipes="selected.result.ranking" :limit="12"/><p class="muted">{{selected.result.warning}}</p></section></template><div v-else class="empty">{{selected?.status==='failed'?selected.error:'运行正在队列中计算，页面每 3 秒更新。'}}</div></template>
